  nextUrl = m[1];
  const cm = nextUrl.match(/[?&]cursor=([^&]+)/);
  if (cm) { try { cursorDecoded = Buffer.from(decodeURIComponent(cm[1]), 'base64').toString('utf8'); } catch (e) { cursorDecoded = null; } }
}

// adaptive pacing from rate-limit headers
const remaining = Number(hdr['x-ratelimit-remaining']);
const reset = Number(hdr['x-ratelimit-reset']);
let waitSeconds = 1;
if (!Number.isNaN(remaining)) {
  if (remaining <= 1) {
    const untilReset = !Number.isNaN(reset) ? reset - Math.floor(Date.now() / 1000) : 10;
    waitSeconds = Math.max(2, Math.min(30, untilReset));
  } else if (remaining <= 5) waitSeconds = 3;
}

const b = j.body;
const count = Array.isArray(b) ? b.length : ((b && (b.events || b.data || b.items)) || []).length || 0;
st.pages += 1; st.events += count;
sd[key] = st;

const hasNext = !!nextUrl && st.pages < 10;
return [{ json: { hasNext, nextUrl, cursorDecoded, waitSeconds, pages: st.pages, historyEvents: st.events, lastStatus: j.statusCode || null } }];

